];

/**
 * ─────────────────────────────────────────────────────────────
 *  GUARDRAIL AR — sanitizador de datos sensibles (formato argentino)
 *  Nodo: Code (JavaScript) · Mode: "Run Once for All Items"
 * ─────────────────────────────────────────────────────────────
 *  Detecta y enmascara: CUIT/CUIL (con dígito verificador), CBU/CVU
 *  (con los dos verificadores del BCRA), alias CBU, DNI, teléfonos AR,
 *  tarjetas (Luhn), email, IP, patentes, SUBE y secretos/API keys.
 *
 *  Salida: mismo item + campo `_guardrail` con el reporte de auditoría.
 */

// ══════════════════════ CONFIGURACIÓN ══════════════════════

const CAMPOS  = ['output'];   // campos a sanitizar. [] = todos los strings del item
const MODO    = 'mask';       // 'mask' (parcial) | 'redact' (total) | 'hash' (seudónimo estable)
const AGRESIVO = false;       // true = también DNI sueltos de 7-8 dígitos y patentes (más falsos positivos)
const BLOQUEAR_SI_HAY = ['CBU', 'TARJETA', 'SECRETO']; // marca el item para desviarlo por un IF
const SALT = 'cambiame-por-algo-random-y-guardalo-en-un-env'; // sólo para MODO 'hash'

// Tus patrones extra (se agregan al motor sin tocar nada más)
const EXTRA = [
  // { tipo: 'LEGAJO', prio: 50, re: /\bLEG-\d{6}\b/g },
];

// ══════════════════════ VALIDADORES ══════════════════════

const soloDig = s => String(s).replace(/\D/g, '');

/** CUIT/CUIL: prefijo válido + dígito verificador módulo 11 */
function cuitOk(d) {
  if (!/^\d{11}$/.test(d)) return false;
  if (!['20','23','24','25','26','27','30','33','34'].includes(d.slice(0, 2))) return false;
  const pesos = [5, 4, 3, 2, 7, 6, 5, 4, 3, 2];
  let suma = 0;
  for (let i = 0; i < 10; i++) suma += Number(d[i]) * pesos[i];
  let v = 11 - (suma % 11);
  if (v === 11) v = 0;
  if (v === 10) v = 9;
  return v === Number(d[10]);
}

/** CBU/CVU: 22 dígitos, verificador en la posición 8 y en la 22 (algoritmo BCRA) */
function cbuOk(d) {
  if (!/^\d{22}$/.test(d)) return false;
  const chk = (bloque, pesos) => {
    let s = 0;
    for (let i = 0; i < pesos.length; i++) s += Number(bloque[i]) * pesos[i];
    return (10 - (s % 10)) % 10;
  };
  const b1 = d.slice(0, 8), b2 = d.slice(8);
  return chk(b1, [7, 1, 3, 9, 7, 1, 3]) === Number(b1[7])
      && chk(b2, [3, 9, 7, 1, 3, 9, 7, 1, 3, 9, 7, 1, 3]) === Number(b2[13]);
}

/** Tarjetas: Luhn */
function luhn(d) {
  if (!/^\d{13,19}$/.test(d)) return false;
  let s = 0, alt = false;
  for (let i = d.length - 1; i >= 0; i--) {
    let n = Number(d[i]);
    if (alt) { n *= 2; if (n > 9) n -= 9; }
    s += n; alt = !alt;
  }
  return s % 10 === 0;
}

/** Teléfono AR: normaliza +54 / 9 / 0 / 15 y exige 10 dígitos (área + abonado) */
function telOk(bruto) {
  let d = soloDig(bruto);
  if (d.startsWith('54')) d = d.slice(2);
  if (d.length === 11 && d.startsWith('9')) d = d.slice(1);
  if (d.startsWith('0')) d = d.slice(1);
  d = d.replace(/^(\d{2,4})15(\d{6,8})$/, '$1$2');
  return d.length === 10;
}

/** Seudónimo estable (FNV-1a). NO es criptográfico: sirve para correlacionar, no para proteger. */
function hash(s) {
  let h = 2166136261;
  const x = SALT + s;
  for (let i = 0; i < x.length; i++) { h ^= x.charCodeAt(i); h = Math.imul(h, 16777619); }
  return (h >>> 0).toString(36).padStart(7, '0');
}

// ══════════════════════ DETECTORES ══════════════════════
// prio alta gana ante solapamientos (un CBU nunca se parte en un CUIT + resto)

const DET = [
  // ── Secretos / credenciales ──────────────────────────────────
  { tipo:'SECRETO', prio:100, re:/-----BEGIN[A-Z ]*PRIVATE KEY-----[\s\S]*?-----END[A-Z ]*PRIVATE KEY-----/g },
  { tipo:'SECRETO', prio:99,  re:/\beyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\b/g },   // JWT
  { tipo:'SECRETO', prio:99,  re:/\b(?:sk|rk|pk)[-_](?:live|test|proj)?[-_]?[A-Za-z0-9_-]{16,}\b/g },   // OpenAI / Stripe
  { tipo:'SECRETO', prio:99,  re:/\bAKIA[0-9A-Z]{16}\b/g },                                             // AWS
  { tipo:'SECRETO', prio:99,  re:/\bAIza[0-9A-Za-z_-]{35}\b/g },                                        // Google
  { tipo:'SECRETO', prio:99,  re:/\b(?:ghp|gho|ghu|ghs|ghr)_[A-Za-z0-9]{36}\b/g },                      // GitHub
  { tipo:'SECRETO', prio:99,  re:/\bxox[baprs]-[A-Za-z0-9-]{10,}\b/g },                                 // Slack
  { tipo:'SECRETO', prio:99,  re:/\b(?:APP_USR|TEST)-[A-Za-z0-9-]{20,}\b/g },                           // Mercado Pago
  { tipo:'SECRETO', prio:98,  grupo:1,
    re:/\b(?:api[_-]?key|apikey|access[_-]?token|token|secret|password|passwd|clave|contrase[nñ]a|authorization|bearer)\b\s*[:=]?\s*["']?([A-Za-z0-9_\-./+=]{12,})["']?/gi },

  // ── Bancario ─────────────────────────────────────────────────
  { tipo:'CBU', prio:90, re:/(?<![\d.\-])\d{22}(?!\d)/g,                        val:m => cbuOk(soloDig(m[0])) },
  { tipo:'CBU', prio:90, re:/(?<![\d.\-])\d{8}[ .\-]\d{14}(?!\d)/g,             val:m => cbuOk(soloDig(m[0])) },
  { tipo:'CBU', prio:90, re:/(?<![\d.\-])(?:\d{4}[ .\-]){5}\d{2}(?!\d)/g,       val:m => cbuOk(soloDig(m[0])) },
  // respaldo: tiene forma de CBU pero el verificador no cierra (typo u ofuscación deliberada)
  { tipo:'CBU', prio:89, re:/(?<![\d.\-])\d{22}(?!\d)/g, soloAgresivo:true },
  { tipo:'ALIAS', prio:88, grupo:1,
    re:/\balias(?:\s*(?:cbu|cvu))?\s*[:=]?\s*([A-Za-z0-9]{2,}(?:[.\-][A-Za-z0-9]{2,}){1,4})/gi },
  { tipo:'TARJETA', prio:85, re:/(?<![\d.\-])(?:\d{4}[ .\-]?){3}\d{1,4}(?!\d)/g, val:m => luhn(soloDig(m[0])) },
  { tipo:'TARJETA', prio:85, re:/(?<![\d.\-])\d{13,19}(?!\d)/g,                  val:m => luhn(soloDig(m[0])) },
  { tipo:'SUBE',    prio:84, re:/(?<![\d.\-])6061\d{12}(?!\d)/g },

  // ── Identidad ────────────────────────────────────────────────
  { tipo:'CUIT', prio:80,
    re:/(?<![\d.\-])(?:20|23|24|25|26|27|30|33|34)[ .\-]?\d{8}[ .\-]?\d(?!\d)/g, val:m => cuitOk(soloDig(m[0])) },
  { tipo:'CUIT', prio:79, soloAgresivo:true,
    re:/(?<![\d.\-])(?:20|23|24|25|26|27|30|33|34)[ .\-]?\d{8}[ .\-]?\d(?!\d)/g },
  { tipo:'DNI', prio:76, grupo:1,
    re:/\b(?:D\.?N\.?I\.?|documento|doc\.?|c[eé]dula|libreta)\b[^\d\n]{0,15}(\d{1,2}[. ]?\d{3}[. ]?\d{3})(?!\d)/gi },
  { tipo:'DNI', prio:70, re:/(?<![\d.\-])\d{1,2}\.\d{3}\.\d{3}(?!\d)/g },
  { tipo:'DNI', prio:60, re:/(?<![\d.\-])\d{7,8}(?!\d)/g, soloAgresivo:true },

  // ── Contacto ─────────────────────────────────────────────────
  { tipo:'EMAIL', prio:79, re:/\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/g },
  { tipo:'TELEFONO', prio:72, val:m => telOk(m[0]),
    re:/(?<![\d\-+])(?:\+?\s?54[\s.\-]?)?(?:9[\s.\-]?)?0?\(?\d{2,4}\)?[\s.\-]?(?:15[\s.\-]?)?\d{3,4}[\s.\-]?\d{4}(?![\d\-])/g },

  // ── Otros ────────────────────────────────────────────────────
  { tipo:'IP', prio:68, re:/\b(?:\d{1,3}\.){3}\d{1,3}\b/g, val:m => m[0].split('.').every(o => Number(o) <= 255) },
  { tipo:'PATENTE', prio:64, soloAgresivo:true,
    re:/\b(?:[A-Z]{2}\s?\d{3}\s?[A-Z]{2}|[A-Z]{3}\s?\d{3}|[A-Z]\d{3}[A-Z]{3})\b/g },

  ...EXTRA,
];

// ══════════════════════ MOTOR ══════════════════════

const VISIBLES = { TARJETA: 4, CBU: 3, CUIT: 1, DNI: 3, TELEFONO: 4, SUBE: 4 };

function enmascarar(valor, tipo) {
  if (MODO === 'redact') return `[${tipo}]`;
  if (MODO === 'hash')   return `[${tipo}#${hash(valor)}]`;

  if (tipo === 'EMAIL') {
    const [loc, dom = ''] = valor.split('@');
    const tapar = s => s[0] + '•'.repeat(Math.max(s.length - 1, 2));
    return `${tapar(loc)}@${dom.replace(/^[^.]+/, tapar)}`;
  }

  let restantes = VISIBLES[tipo] ?? 0;
  if (!restantes) return `[${tipo}]`;

  let out = '';
  for (let i = valor.length - 1; i >= 0; i--) {
    const c = valor[i];
    if (!/[0-9A-Za-z]/.test(c)) { out = c + out; continue; }
    if (restantes > 0) { restantes--; out = c + out; }
    else out = '•' + out;
  }
  return out;
}

function escanear(texto) {
  const hallazgos = [];

  for (const d of DET) {
    if (d.soloAgresivo && !AGRESIVO) continue;
    const re = new RegExp(d.re.source, d.re.flags.includes('g') ? d.re.flags : d.re.flags + 'g');
    let m;
    while ((m = re.exec(texto)) !== null) {
      if (m[0] === '') { re.lastIndex++; continue; }
      if (d.val && !d.val(m)) continue;

      let valor = m[0], inicio = m.index;
      if (d.grupo && m[d.grupo]) {            // enmascarar sólo el grupo, no la etiqueta
        valor = m[d.grupo];
        inicio = m.index + m[0].lastIndexOf(valor);
      }
      hallazgos.push({ tipo: d.tipo, prio: d.prio, valor, inicio, fin: inicio + valor.length });
    }
  }

  // resolución de solapamientos: gana la prioridad más alta, luego el match más largo
  hallazgos.sort((a, b) => b.prio - a.prio || (b.fin - b.inicio) - (a.fin - a.inicio) || a.inicio - b.inicio);
  const elegidos = [];
  for (const h of hallazgos) {
    if (elegidos.some(e => h.inicio < e.fin && h.fin > e.inicio)) continue;
    elegidos.push(h);
  }
  elegidos.sort((a, b) => a.inicio - b.inicio);

  let out = '', cursor = 0;
  for (const h of elegidos) {
    out += texto.slice(cursor, h.inicio) + enmascarar(h.valor, h.tipo);
    cursor = h.fin;
  }
  out += texto.slice(cursor);

  return { texto: out, hallazgos: elegidos.map(h => ({ tipo: h.tipo, pos: h.inicio })) };
}

function recorrer(valor, aplicar) {
  if (typeof valor === 'string') return aplicar(valor);
  if (Array.isArray(valor)) return valor.map(v => recorrer(v, aplicar));
  if (valor && typeof valor === 'object') {
    const o = {};
    for (const k of Object.keys(valor)) o[k] = recorrer(valor[k], aplicar);
    return o;
  }
  return valor;
}

// ══════════════════════ SALIDA ══════════════════════

const salida = [];

$input.all().forEach((item, i) => {
  const reporte = [];
  const aplicar = txt => {
    const r = escanear(txt);
    reporte.push(...r.hallazgos);
    return r.texto;
  };

  let json;
  if (CAMPOS.length) {
    json = { ...item.json };
    for (const c of CAMPOS) if (json[c] !== undefined) json[c] = recorrer(json[c], aplicar);
  } else {
    json = recorrer(item.json, aplicar);
  }

  const tipos = [...new Set(reporte.map(h => h.tipo))];
  json._guardrail = {
    limpio: tipos.length === 0,
    tipos,
    total: reporte.length,
    bloquear: tipos.some(t => BLOQUEAR_SI_HAY.includes(t)),
    modo: MODO,
  };

  salida.push({ json, pairedItem: i });
});

return salida;

return $input.all().map(item => {
  const text = item.json.output;

  if (!text) {
    throw new Error('No se encontró el texto de respuesta de la IA');
  }

  try {
    const parsed = JSON.parse(text);

    return {
      json: parsed
    };
  } catch (error) {
    throw new Error(`La respuesta de la IA no contiene un JSON válido: ${text}`);
  }
});

return $input.all().map(item => {
  const text = item.json.output;

  if (!text) {
    throw new Error('No se encontró el texto de respuesta de la IA');
  }

  try {
    const parsed = JSON.parse(text);

    return {
      json: parsed
    };
  } catch (error) {
    throw new Error(`La respuesta de la IA no contiene un JSON válido: ${text}`);
  }
});

/**
 * ─────────────────────────────────────────────────────────────
 *  GUARDRAIL AR — ENTRADA · medios de pago
 *  Nodo: Code (JavaScript) · Mode: "Run Once for All Items"
 *  Ubicación: PRIMER nodo después del trigger. Antes de logs, antes del agente.
 * ─────────────────────────────────────────────────────────────
 *
 *  Detecta PAN (Luhn + ventana deslizante + BIN argentino), CVV, vencimiento,
 *  titular, PIN, banda magnética, CBU/CVU y alias.
 *
 *  Decide entre BLOQUEAR el item o TOKENIZAR y dejarlo pasar.
 *  El CVV / PIN / track data NUNCA se tokeniza: se destruye siempre.
 */

// ══════════════════════ CONFIGURACIÓN ══════════════════════

const CAMPOS = ['chatInput', 'message', 'body', 'text']; // primero que exista; [] = todo el JSON

// Qué hacer con cada tipo: 'bloquear' | 'tokenizar' | 'eliminar'
const POLITICA = {
  PAN:        'bloquear',    // número de tarjeta
  CVV:        'bloquear',    // nunca almacenable, ni cifrado (PCI DSS 3.2)
  TRACK:      'bloquear',    // banda magnética / chip dump
  PIN:        'bloquear',
  VENCIMIENTO:'eliminar',
  TITULAR:    'eliminar',
  CBU:        'tokenizar',
  ALIAS:      'tokenizar',
};

const EXIGIR_MARCA = false; // true = solo marca PAN si el BIN es conocido (menos falsos positivos,
                            // más falsos negativos). false = Luhn + longitud alcanza.
const DETECTAR_DELETREADO = true; // "cuatro cinco cero nueve..." en chatbots de voz/texto

const RESPUESTA_SEGURA =
  'Por seguridad no puedo recibir datos de tarjeta, CVV ni claves por este canal. ' +
  'Si necesitás hacer un pago, te paso el link seguro y los cargás vos directamente.';

// ══════════════════════ TABLA DE BIN (AR) ══════════════════════

const MARCAS = [
  ['AMEX',        /^3[47]/,                                        [15]],
  ['DINERS',      /^3(?:0[0-5]|095|6|8)/,                          [14, 16]],
  ['NARANJA',     /^(?:589562|40291[78]|52757[12]|37779[89])/,     [16]],
  ['CABAL',       /^(?:589657|60420[1-9]|627170|6042|6043|6044)/,  [16]],
  ['ARGENCARD',   /^50110[45]/,                                    [16]],
  ['NATIVA',      /^589634/,                                       [16]],
  ['SHOPPING',    /^(?:603488|603493|27995)/,                      [16]],
  ['MAESTRO',     /^(?:5018|5020|5038|5[6-8]|6304|6759|676[1-3])/, [12,13,14,15,16,17,18,19]],
  ['MASTERCARD',  /^(?:5[1-5]|2[2-7])/,                            [16]],
  ['VISA',        /^4/,                                            [13, 16, 19]],
  ['DISCOVER',    /^(?:6011|64[4-9]|65)/,                          [16, 19]],
];

function marcaDe(pan) {
  for (const [nombre, re, largos] of MARCAS) {
    if (re.test(pan) && largos.includes(pan.length)) return nombre;
  }
  return null;
}

// ══════════════════════ VALIDADORES ══════════════════════

const soloDig = s => String(s).replace(/\D/g, '');

function luhn(d) {
  if (!/^\d{12,19}$/.test(d)) return false;
  let s = 0, alt = false;
  for (let i = d.length - 1; i >= 0; i--) {
    let n = Number(d[i]);
    if (alt) { n *= 2; if (n > 9) n -= 9; }
    s += n; alt = !alt;
  }
  return s % 10 === 0;
}

function cbuOk(d) {
  if (!/^\d{22}$/.test(d)) return false;
  const chk = (b, p) => {
    let s = 0;
    for (let i = 0; i < p.length; i++) s += Number(b[i]) * p[i];
    return (10 - (s % 10)) % 10;
  };
  const b1 = d.slice(0, 8), b2 = d.slice(8);
  return chk(b1, [7,1,3,9,7,1,3]) === Number(b1[7])
      && chk(b2, [3,9,7,1,3,9,7,1,3,9,7,1,3]) === Number(b2[13]);
}

function cuitOk(d) {
  if (!/^\d{11}$/.test(d)) return false;
  if (!['20','23','24','25','26','27','30','33','34'].includes(d.slice(0,2))) return false;
  const p = [5,4,3,2,7,6,5,4,3,2];
  let s = 0;
  for (let i = 0; i < 10; i++) s += Number(d[i]) * p[i];
  let v = 11 - (s % 11);
  if (v === 11) v = 0;
  if (v === 10) v = 9;
  return v === Number(d[10]);
}

// ══════════════════════ ESCANEO DE PAN ══════════════════════
// Corridas de dígitos con separadores arbitrarios → ventana deslizante 19→12 con Luhn.
// Resiste "4509 95 35 662 337 04", "4509-9535.6623 3704" y agrupaciones raras.

// Segunda capa: forma + contexto. Dispara aunque Luhn falle (typos, números de prueba,
// tarjetas con BIN nuevo). Es la capa que importa en un guardrail de ENTRADA.

const CONTEXTO_PAGO = /(?:tarjeta|tarj\.?|visa|mastercard|master\b|amex|american\s*express|cabal|naranja|argencard|maestro|d[eé]bito|cr[eé]dito|pl[aá]stico|card|pago\s*con|te\s*paso\s*(?:la|el))/i;

const AGRUPACIONES = [
  /^\d{4}[ .\-]\d{4}[ .\-]\d{4}[ .\-]\d{1,4}$/,  // Visa / Mastercard / Maestro
  /^\d{4}[ .\-]\d{6}[ .\-]\d{5}$/,               // Amex
  /^\d{4}[ .\-]\d{6}[ .\-]\d{4}$/,               // Diners
];

function sospechaPAN(bruto, d, base, texto) {
  if (d.length < 13 || d.length > 19) return null;

  // Regla A — agrupación típica de tarjeta
  if (AGRUPACIONES.some(re => re.test(bruto.trim()))) {
    return { motivo: 'formato' };
  }
  // Regla B — palabra de medio de pago en los 45 caracteres previos
  const antes = texto.slice(Math.max(0, base - 45), base);
  if (CONTEXTO_PAGO.test(antes)) {
    return { motivo: 'contexto' };
  }
  return null;
}

function escanearPAN(texto) {
  const out = [];
  const corridas = /\d(?:[ .\-\u00A0]?\d){11,}/g;
  let m;

  while ((m = corridas.exec(texto)) !== null) {
    const bruto = m[0], base = m.index;
    const pos = [], digs = [];
    for (let i = 0; i < bruto.length; i++) {
      if (/\d/.test(bruto[i])) { pos.push(base + i); digs.push(bruto[i]); }
    }
    const d = digs.join('');

    // La corrida entera es otra cosa conocida: no buscar tarjetas adentro
    if (d.length === 22 && cbuOk(d)) {
      out.push({ tipo: 'CBU', inicio: pos[0], fin: pos[21] + 1, meta: d.slice(-3), conf: 'alta' });
      continue;
    }
    if (d.length === 11 && cuitOk(d)) continue; // CUIT: lo maneja otro detector, no es medio de pago

    // Ventana ANCLADA: el primer candidato arranca donde arranca la corrida.
    // Solo se avanza después de un match confirmado (permite dos tarjetas pegadas,
    // pero evita "encontrar" una tarjeta en el medio de un nº de pedido largo).
    let i = 0, huboHit = false;
    while (i <= d.length - 13) {
      let hit = false;
      for (let len = Math.min(19, d.length - i); len >= 13; len--) {
        const cand = d.slice(i, i + len);
        if (!luhn(cand)) continue;
        const marca = marcaDe(cand);
        if (EXIGIR_MARCA && !marca) continue;
        if (!marca && len !== 16 && len !== 15) continue; // sin BIN, solo largos plausibles
        out.push({
          tipo: 'PAN',
          inicio: pos[i],
          fin: pos[i + len - 1] + 1,
          meta: `${marca || 'TARJETA'} ••••${cand.slice(-4)}`,
          conf: marca ? 'alta' : 'media',
        });
        i += len; hit = true; huboHit = true; break;
      }
      if (!hit) break;
    }

    // No validó Luhn en ningún corte: ¿tiene forma o contexto de tarjeta igual?
    if (!huboHit) {
      const s = sospechaPAN(bruto, d, base, texto);
      if (s) out.push({
        tipo: 'PAN',
        inicio: pos[0],
        fin: pos[pos.length - 1] + 1,
        meta: `TARJETA ••••${d.slice(-4)}`,
        conf: 'baja',
        motivo: s.motivo,
      });
    }
  }
  return out;
}

// ══════════════════════ DETECTORES CONTEXTUALES ══════════════════════

const DET = [
  // Banda magnética / dump de track 1 y 2 — máxima prioridad
  { tipo:'TRACK', prio:100, re:/%B\d{12,19}\^[^^\n]{2,30}\^\d{4}[^?\n]*\??/g },
  { tipo:'TRACK', prio:100, re:/;\d{12,19}=\d{4}[^?\n]*\??/g },

  // CVV / código de seguridad — solo con contexto (3-4 dígitos sueltos no dicen nada)
  { tipo:'CVV', prio:95, grupo:1,
    re:/\b(?:cvv2?|cvc2?|csc|cid|c[oó]d(?:igo)?\.?\s*(?:de\s*)?seg(?:uridad)?|c[oó]digo\s*(?:de\s*)?verificaci[oó]n|los\s*(?:tres|3)\s*d[ií]gitos)\b[^\d\n]{0,12}(\d{3,4})\b/gi },

  // PIN / clave de cajero
  { tipo:'PIN', prio:94, grupo:1,
    re:/\b(?:pin|clave(?:\s*(?:de\s*)?(?:cajero|tarjeta|home\s*banking))?|contrase[nñ]a\s*(?:de\s*)?(?:cajero|tarjeta))\b[^\d\n]{0,12}(\d{4,8})\b/gi },

  // Vencimiento
  { tipo:'VENCIMIENTO', prio:80, grupo:1,
    re:/\b(?:vto\.?|vence|vencimiento|expira|exp\.?|valid\s*(?:thru|hasta)|caduca)\b[^\d\n]{0,12}((?:0?[1-9]|1[0-2])\s*[\/\-.]\s*(?:20)?\d{2})\b/gi },

  // Titular
  { tipo:'TITULAR', prio:78, grupo:1,
    re:/\b(?:titular|cardholder|nombre\s*(?:que\s*figura\s*)?(?:en|de)\s*la\s*tarjeta)\b\s*[:=]?\s*([A-ZÁÉÍÓÚÑ][a-záéíóúñ]+(?:\s+[A-ZÁÉÍÓÚÑ][a-záéíóúñ]+){1,3})/g },

  // Alias CBU/CVU
  { tipo:'ALIAS', prio:70, grupo:1,
    re:/\balias(?:\s*(?:cbu|cvu))?\s*[:=]?\s*([A-Za-z0-9]{2,}(?:[.\-][A-Za-z0-9]{2,}){1,4})/gi },
];

// Dígitos deletreados: "cuatro cinco cero nueve ..." (>=12 seguidos)
const PALABRA_DIG = { cero:'0', o:'0', uno:'1', una:'1', dos:'2', tres:'3', cuatro:'4',
  cinco:'5', seis:'6', siete:'7', ocho:'8', nueve:'9' };

function escanearDeletreado(texto) {
  if (!DETECTAR_DELETREADO) return [];
  const out = [];
  const re = /\b([a-záéíóúñ]+)\b/gi;
  let m, corrida = [], iniPos = null, finPos = null;
  const cerrar = () => {
    if (corrida.length >= 12) out.push({ tipo:'PAN', inicio:iniPos, fin:finPos, meta:'TARJETA deletreada', conf:'media' });
    corrida = []; iniPos = null;
  };
  while ((m = re.exec(texto)) !== null) {
    const w = m[1].toLowerCase();
    if (PALABRA_DIG[w] !== undefined) {
      if (iniPos === null) iniPos = m.index;
      corrida.push(PALABRA_DIG[w]);
      finPos = m.index + m[1].length;
    } else cerrar();
  }
  cerrar();
  return out;
}

// ══════════════════════ MOTOR ══════════════════════

function reemplazo(h) {
  const acc = POLITICA[h.tipo] || 'eliminar';
  if (acc === 'tokenizar') {
    if (h.tipo === 'CBU')   return `[CBU ••••${h.meta}]`;
    if (h.tipo === 'ALIAS') return '[ALIAS]';
    if (h.tipo === 'PAN')   return `[${h.meta}]`;   // marca + últimos 4 = dato almacenable
  }
  return `[${h.tipo} ELIMINADO]`;
}

function escanear(texto) {
  const hallazgos = [
    ...escanearPAN(texto).map(h => ({ ...h, prio: h.tipo === 'CBU' ? 90 : 92 })),
    ...escanearDeletreado(texto).map(h => ({ ...h, prio: 91 })),
  ];

  for (const d of DET) {
    const re = new RegExp(d.re.source, d.re.flags.includes('g') ? d.re.flags : d.re.flags + 'g');
    let m;
    while ((m = re.exec(texto)) !== null) {
      if (m[0] === '') { re.lastIndex++; continue; }
      let valor = m[0], inicio = m.index;
      if (d.grupo && m[d.grupo]) {
        valor = m[d.grupo];
        inicio = m.index + m[0].lastIndexOf(valor);
      }
      hallazgos.push({ tipo: d.tipo, prio: d.prio, inicio, fin: inicio + valor.length, meta: null, conf: 'alta' });
    }
  }

  hallazgos.sort((a, b) => b.prio - a.prio || (b.fin - b.inicio) - (a.fin - a.inicio) || a.inicio - b.inicio);
  const elegidos = [];
  for (const h of hallazgos) {
    if (elegidos.some(e => h.inicio < e.fin && h.fin > e.inicio)) continue;
    elegidos.push(h);
  }
  elegidos.sort((a, b) => a.inicio - b.inicio);

  // Si apareció un PAN, todo MM/AA suelto en el mismo texto pasa a ser vencimiento
  if (elegidos.some(h => h.tipo === 'PAN')) {
    const re = /\b(0[1-9]|1[0-2])\s*[\/\-]\s*(2[5-9]|3[0-9])\b/g;
    let m;
    while ((m = re.exec(texto)) !== null) {
      const ini = m.index, fin = ini + m[0].length;
      if (!elegidos.some(e => ini < e.fin && fin > e.inicio)) {
        elegidos.push({ tipo:'VENCIMIENTO', prio:80, inicio:ini, fin, meta:null, conf:'media' });
      }
    }
    elegidos.sort((a, b) => a.inicio - b.inicio);
  }

  let out = '', cursor = 0;
  for (const h of elegidos) {
    out += texto.slice(cursor, h.inicio) + reemplazo(h);
    cursor = h.fin;
  }
  out += texto.slice(cursor);

  return { texto: out, hallazgos: elegidos };
}

function recorrer(v, fn) {
  if (typeof v === 'string') return fn(v);
  if (Array.isArray(v)) return v.map(x => recorrer(x, fn));
  if (v && typeof v === 'object') {
    const o = {};
    for (const k of Object.keys(v)) o[k] = recorrer(v[k], fn);
    return o;
  }
  return v;
}

// ══════════════════════ SALIDA ══════════════════════

const salida = [];

$input.all().forEach((item, i) => {
  const reporte = [];
  const fn = txt => {
    const r = escanear(txt);
    reporte.push(...r.hallazgos);
    return r.texto;
  };

  let json;
  if (CAMPOS.length) {
    json = { ...item.json };
    for (const c of CAMPOS) if (typeof json[c] !== 'undefined') json[c] = recorrer(json[c], fn);
  } else {
    json = recorrer(item.json, fn);
  }

  const tipos = [...new Set(reporte.map(h => h.tipo))];
  const bloquear = tipos.some(t => POLITICA[t] === 'bloquear');

  // El reporte NO incluye valores, solo metadatos: es para auditar, no para filtrar de nuevo
  json._guardrail = {
    limpio: tipos.length === 0,
    tipos,
    total: reporte.length,
    bloquear,
    accion: bloquear ? 'bloquear' : 'continuar',
    detalle: reporte.map(h => ({ tipo: h.tipo, confianza: h.conf, ...(h.meta ? { ref: h.meta } : {}) })),
    ...(bloquear ? { respuesta_segura: RESPUESTA_SEGURA } : {}),
  };

  salida.push({ json, pairedItem: i });
});

return salida;

// 1. Obtener el texto correcto
const raw = $json.content.parts[0].text;

// 2. Limpiar ```json
const cleaned = raw
